__version__ = "0.1.2"

"""Objects attached to a face, following it when it moves.

A cylinder stands on a cube. The cube is made taller, wider, moved: the
cylinder should stay on its top face and keep its place there, measured
the way it was attached. Nothing links by itself; `attach` makes each link (and `unattach` takes one away),
and says how the object keeps its place sideways:

- "distance": its distance from a point of the face (a corner, the middle
  of an edge, the centre) stays the same, like a hole dimensioned from an
  edge;
- "proportion": its place as a share of the face stays the same, so a
  cylinder in the middle stays in the middle.

Up and down it rides the face. A link follows its own face only, unless it
was made to follow a chain too: then it also moves when the face it stands
on is itself moved by an attachment of its own.

A link lives in the follower's user text, as JSON, with what it last saw of
the face. Saving, undo and redo therefore carry it with the object, and a
change is found by comparing the face with what the link last saw rather
than by being told what changed: the scene's listeners are told only that
something did.
"""


import json

import numpy as np

from serpentine3d.core import user_text

KEY = "attachment"        # the user text key a link is kept under
_PARALLEL = 1 - 1e-7


class AttachError(Exception):
    """The link cannot be made, or its face cannot be found any more."""


# --- reading a face ---------------------------------------------------------

def _frame(normal):
    """Two directions across a face: along the world's X where they can be,
    so a box drawn on the world reads its sides as X and Y."""
    n = np.asarray(normal, float)
    ref = np.array([1.0, 0.0, 0.0]) if abs(n[0]) < 0.9 else \
        np.array([0.0, 1.0, 0.0])
    u = ref - np.dot(ref, n) * n
    u /= np.linalg.norm(u)
    return u, np.cross(n, u)


def _planar_faces(shape):
    """[(face, normal, offset along it)] for every flat face of a shape."""
    from OCP.BRepAdaptor import BRepAdaptor_Surface
    from OCP.GeomAbs import GeomAbs_SurfaceType
    from serpentine3d.core.geometry import faces_of
    out = []
    for face in faces_of(shape):
        s = BRepAdaptor_Surface(face)
        if s.GetType() != GeomAbs_SurfaceType.GeomAbs_Plane:
            continue
        ax = s.Plane().Axis()
        d, p = ax.Direction(), ax.Location()
        n = np.array([d.X(), d.Y(), d.Z()])
        out.append((face, n, np.array([p.X(), p.Y(), p.Z()])))
    return out


def _vertices(face):
    from serpentine3d.core import occ
    pts = []
    exp = occ.TopExp_Explorer(face, occ.VERTEX)
    while exp.More():
        p = occ.point_of_vertex(occ.to_vertex(exp.Current()))
        pts.append((p.X(), p.Y(), p.Z()))
        exp.Next()
    return np.asarray(pts, float)


def face_state(shape, normal) -> dict | None:
    """Where the face is now: the flat face of `shape` that faces `normal`
    and lies furthest along it (a cube's top, for a normal pointing up).
    Its height along the normal and its extent across it."""
    n = np.asarray(normal, float)
    best = None
    for face, fn, p in _planar_faces(shape):
        if abs(float(np.dot(fn, n))) <= _PARALLEL:
            continue
        h = float(np.dot(p, n))
        if best is None or h > best[0]:
            best = (h, face)
    if best is None:
        return None
    u, v = _frame(n)
    pts = _vertices(best[1])
    across = np.column_stack((pts @ u, pts @ v))
    return {"h": best[0], "lo": across.min(axis=0).tolist(),
            "hi": across.max(axis=0).tolist()}


def _reference(shape, normal):
    """Where a follower stands across the face: the middle of its box."""
    from serpentine3d.core.geometry import bbox
    lo, hi = bbox(shape)
    centre = (np.asarray(lo) + np.asarray(hi)) / 2
    u, v = _frame(normal)
    return np.array([float(centre @ u), float(centre @ v)])


# --- making a link ----------------------------------------------------------

def make_link(parent, face, follower, anchor=None, mode="distance",
              chain=False) -> dict:
    """The link that keeps `follower` on `face` of `parent`.

    `anchor` is a world point the follower is measured from, or None for
    the face's centre; it is kept as its place across the face, so it moves
    with the face when the face changes size."""
    from OCP.BRepAdaptor import BRepAdaptor_Surface
    from OCP.GeomAbs import GeomAbs_SurfaceType
    s = BRepAdaptor_Surface(face)
    if s.GetType() != GeomAbs_SurfaceType.GeomAbs_Plane:
        raise AttachError("only a flat face can carry an attachment")
    if parent.id == follower.id:
        raise AttachError("an object cannot be attached to itself")
    d = s.Plane().Axis().Direction()
    n = np.array([d.X(), d.Y(), d.Z()])
    p0 = s.Plane().Axis().Location()
    h = float(np.dot([p0.X(), p0.Y(), p0.Z()], n))
    # the link names the face as the furthest one along its normal, so the
    # normal is turned to point out of the face that was picked
    heights = [float(np.dot(p, n)) for _f, fn, p in
               _planar_faces(parent.shape) if abs(float(np.dot(fn, n)))
               > _PARALLEL]
    tol = 1e-9 * max(1.0, abs(h))
    if heights and h < max(heights) - tol:
        n, h = -n, -h
        if h < max(-x for x in heights) - tol:
            raise AttachError("that face is inside the object, not on its "
                              "outside; attach to an outer face")
    state = face_state(parent.shape, n)
    if state is None:
        raise AttachError("the face cannot be found on its object")
    lo, hi = np.asarray(state["lo"]), np.asarray(state["hi"])
    size = np.maximum(hi - lo, 1e-12)
    u, v = _frame(n)
    if anchor is None:
        fraction = np.array([0.5, 0.5])
    else:
        a = np.asarray(anchor, float)
        fraction = (np.array([a @ u, a @ v]) - lo) / size
    at = _reference(follower.shape, n)
    link = {"parent": parent.id, "normal": n.tolist(), "face": state,
            "anchor": fraction.tolist(), "mode": mode, "chain": bool(chain),
            "at": at.tolist()}
    _remember_place(link)
    return link


def _remember_place(link):
    """The follower's place, in the terms its mode keeps."""
    lo, hi = np.asarray(link["face"]["lo"]), np.asarray(link["face"]["hi"])
    size = np.maximum(hi - lo, 1e-12)
    at = np.asarray(link["at"])
    if link["mode"] == "proportion":
        link["keep"] = ((at - lo) / size).tolist()
    else:
        anchor = lo + np.asarray(link["anchor"]) * size
        link["keep"] = (at - anchor).tolist()


def link_of(obj) -> dict | None:
    text = user_text.value_of(obj.user_text, KEY)
    if text is None:
        return None
    try:
        return json.loads(text)
    except ValueError:
        return None


def with_link(text, link) -> dict | None:
    return user_text.with_value(text, KEY,
                                json.dumps(link) if link else "")


# --- following ----------------------------------------------------------------

def _same(a, b, tol) -> bool:
    return (abs(a["h"] - b["h"]) <= tol
            and np.allclose(a["lo"], b["lo"], atol=tol)
            and np.allclose(a["hi"], b["hi"], atol=tol))


def follow(scene) -> int:
    """Move every follower whose face has moved since its link last looked.
    Returns how many moved. A follower moved by hand keeps its new place:
    the link measures it again rather than putting it back."""
    from serpentine3d.core.geometry import translate
    followers = [(o, link_of(o)) for o in scene.all()]
    followers = [(o, lk) for o, lk in followers if lk is not None]
    if not followers:
        return 0
    moved_here = set()
    count = 0
    for _round in range(len(followers) + 1):
        progress = False
        for obj, link in followers:
            obj = scene.get(obj.id)
            parent = scene.get(link["parent"])
            if obj is None or parent is None:
                continue
            n = np.asarray(link["normal"])
            now = face_state(parent.shape, n)
            if now is None:
                continue
            scale = max(1.0, *(abs(c) for c in now["lo"] + now["hi"]))
            tol = 1e-9 * scale
            at = _reference(obj.shape, n)
            if not np.allclose(at, link["at"], atol=tol):
                link["at"] = at.tolist()      # moved by hand: measure again
                _remember_place(link)
                scene.update(obj.id, user_text=with_link(obj.user_text, link))
                obj = scene.get(obj.id)
            if _same(now, link["face"], tol):
                continue
            progress = True
            if parent.id in moved_here and not link.get("chain"):
                # its face moved only because its own attachment moved it:
                # a link that does not chain just takes note
                link["face"] = now
                scene.update(obj.id, user_text=with_link(obj.user_text, link))
                continue
            target = _target(link, now)
            u, v = _frame(n)
            delta = ((target[0] - at[0]) * u + (target[1] - at[1]) * v
                     + (now["h"] - link["face"]["h"]) * n)
            link["face"] = now
            link["at"] = target.tolist()
            scene.replace_shape(obj.id, translate(obj.shape, tuple(delta)))
            fresh = scene.get(obj.id)
            scene.update(obj.id, user_text=with_link(fresh.user_text, link))
            moved_here.add(obj.id)
            count += 1
        if not progress:
            break
    return count


def _target(link, face) -> np.ndarray:
    lo, hi = np.asarray(face["lo"]), np.asarray(face["hi"])
    size = hi - lo
    keep = np.asarray(link["keep"])
    if link["mode"] == "proportion":
        return lo + keep * size
    return lo + np.asarray(link["anchor"]) * size + keep


class _Watcher:
    """Calls follow() after every change to a scene's objects, once."""

    def __init__(self, scene):
        self.scene = scene
        self.busy = False
        scene.add_listener(self, kinds=("objects",))

    def __call__(self):
        if self.busy:
            return
        self.busy = True
        try:
            follow(self.scene)
        finally:
            self.busy = False


def watch(scene):
    """Make the scene's attachments follow their faces from now on."""
    if getattr(scene, "_attachments_watched", None) is None:
        scene._attachments_watched = _Watcher(scene)
    return scene._attachments_watched

import sys

from serpentine3d.commands.base import OptionReq, SelectReq
from serpentine3d.core import geometry as g


def serpentine3d_plugin(ctx):
    command = ctx.command
    if ctx.scene is not None:
        watch(ctx.scene)          # links saved in an open file follow too

    @command("attach")
    def cmd_attach(ctx):
        """Attach an object to a face, so it follows when the face moves.

        Ctrl+Shift-click the face it sits on first (a cube's top). Then pick
        the object, the point it is measured from (a corner, an edge, any
        point; Enter for the face's centre), and how it keeps its place
        sideways: the same distance from that point, or the same share of the
        face. Up and down it rides the face. A link follows its own face only,
        unless asked to follow a chain too. unattach takes a link away."""
        at = sys.modules[__name__]
        from serpentine3d.commands.base import PointReq
        faces = [(oid, i) for oid, kind, i in ctx.selection.subobjects
                 if kind == "face"]
        if len(faces) != 1:
            ctx.echo("Ctrl+Shift-click the one face the object sits on first, "
                     "then run attach.")
            return
        parent_id, index = faces[0]
        parent = ctx.scene.get(parent_id)
        if parent is None:
            return
        face = g.faces_of(parent.shape)[index]
        picked = yield SelectReq("Select the object to attach to that face",
                                 max_count=1, allow_preselected=False)
        follower = picked[0]
        anchor = yield PointReq("Point it is measured from (Enter for the "
                                "face's centre)", allow_empty=True,
                                extra_options=("Centre",))
        if anchor in (None, "Centre"):
            anchor, where = None, "the face's centre"
        else:
            where = "the picked point"
        mode = yield OptionReq("Sideways, it keeps its",
                               options=["Distance", "Proportion"],
                               default="Distance")
        chain = yield OptionReq("Also follow when that face is moved by an "
                                "attachment of its own?", options=["No", "Yes"],
                                default="No")
        try:
            link = at.make_link(parent, face, follower, anchor, mode.lower(),
                                chain == "Yes")
        except at.AttachError as exc:
            ctx.echo(f"Not attached: {exc}.")
            return
        ctx.scene.update(follower.id,
                         user_text=at.with_link(follower.user_text, link))
        at.watch(ctx.scene)
        keeps = ("its distance from " + where if mode == "Distance"
                 else "its share of the face")
        ctx.echo(f"{follower.name} attached to {parent.name}: it rides that "
                 f"face and keeps {keeps}"
                 + (", and follows a chain." if chain == "Yes" else "."))

    @command("unattach")
    def cmd_unattach(ctx):
        """Take away the attachment of the selected objects."""
        at = sys.modules[__name__]
        objs = yield SelectReq("Select attached objects to unattach")
        done = 0
        for o in objs:
            if at.link_of(o) is not None:
                ctx.scene.update(o.id, user_text=at.with_link(o.user_text, None))
                done += 1
        ctx.echo(f"Unattached {done} object(s)." if done
                 else "None of those is attached.")
